function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments must be lists of the same length.';
  if (operations[0] !== 'AuthenticationManager' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with AuthenticationManager and its timeToLive.';
  const timeToLive = args[0][0];
  if (!Number.isInteger(timeToLive) || timeToLive < 1 || timeToLive > 1e8) return 'timeToLive is an integer from 1 to 10^8.';
  if (operations.length - 1 > 2000) return 'At most 2000 calls in total.';
  const isTime = t => Number.isInteger(t) && t >= 1 && t <= 1e8;
  const isId = id => typeof id === 'string' && /^[a-z]{1,5}$/.test(id);
  const generated = new Set();
  let last = 0;
  for (let i = 1; i < operations.length; i++) {
    const call = args[i];
    let time;
    if (operations[i] === 'generate' || operations[i] === 'renew') {
      if (!Array.isArray(call) || call.length !== 2 || !isId(call[0])) return `${operations[i]} needs a tokenId of 1 to 5 lowercase letters and a time.`;
      time = call[1];
      if (operations[i] === 'generate') {
        if (generated.has(call[0])) return 'Each tokenId can be generated only once.';
        generated.add(call[0]);
      }
    } else if (operations[i] === 'countUnexpiredTokens') {
      if (!Array.isArray(call) || call.length !== 1) return 'countUnexpiredTokens needs one time.';
      time = call[0];
    } else return 'Only generate, renew and countUnexpiredTokens can follow the constructor.';
    if (!isTime(time)) return 'currentTime is an integer from 1 to 10^8.';
    if (time <= last) return 'currentTime must strictly increase from call to call.';
    last = time;
  }
  return null;
}

