class AuthenticationManager {
  constructor(timeToLive) {
    this.timeToLive = timeToLive;
    this.expiries = new Map();
  }

  generate(tokenId, currentTime) {
    this.expiries.set(tokenId, currentTime + this.timeToLive);
  }

  renew(tokenId, currentTime) {
    this.removeExpired(currentTime);
    if (!this.expiries.has(tokenId)) {
      return;
    }
    this.expiries.delete(tokenId);
    this.expiries.set(tokenId, currentTime + this.timeToLive);
  }

  countUnexpiredTokens(currentTime) {
    this.removeExpired(currentTime);
    return this.expiries.size;
  }

  removeExpired(currentTime) {
    for (const [tokenId, expiry] of this.expiries) {
      if (expiry > currentTime) {
        break;
      }
      this.expiries.delete(tokenId);
    }
  }
}

