class AuthenticationManager {
  // A plain list of tokens, scanned in full on every call.
  constructor(timeToLive) {
    this.life = timeToLive;
    this.tokens = [];
  }
  generate(tokenId, currentTime) {
    this.tokens.push({ id: tokenId, until: currentTime + this.life });
  }
  renew(tokenId, currentTime) {
    for (const token of this.tokens) {
      if (token.id === tokenId && token.until > currentTime) token.until = currentTime + this.life;
    }
  }
  countUnexpiredTokens(currentTime) {
    let alive = 0;
    for (const token of this.tokens) if (token.until > currentTime) alive++;
    return alive;
  }
}

