function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const timeToLive = large ? 1 + pick(rand() < 0.5 ? 100000 : 1e8) : 1 + pick(6);
  const calls = large ? 499 : 1 + pick(12);
  const step = large ? Math.max(1, Math.min(Math.floor(timeToLive / 20), 199999)) : 3;
  const letters = large ? 'abcdefghijklmnopqrstuvwxyz' : 'abcdef';
  const used = [];
  const newId = () => {
    for (let tries = 0; tries < 50; tries++) {
      let id = '';
      const length = large ? 1 + pick(5) : 1;
      for (let k = 0; k < length; k++) id += letters[pick(letters.length)];
      if (!used.includes(id)) return id;
    }
    return null;
  };
  const operations = ['AuthenticationManager'];
  const args = [[timeToLive]];
  let time = pick(3);
  for (let c = 0; c < calls; c++) {
    time += 1 + pick(step);
    if (time > 1e8) break;
    const roll = rand();
    if (roll < 0.4) {
      const id = newId();
      if (id !== null) {
        used.push(id);
        operations.push('generate');
        args.push([id, time]);
        continue;
      }
    }
    if (roll < 0.75) {
      const id = used.length && rand() < 0.8 ? used[pick(used.length)] : letters[pick(letters.length)];
      operations.push('renew');
      args.push([id, time]);
    } else {
      operations.push('countUnexpiredTokens');
      args.push([time]);
    }
  }
  return [operations, args];
}
